const {log,uid} = require('./utils'),
open = require('opn'),
axios = require('axios'),
baseURL = 'http://devs.opensi.co'

const curl = axios.create({
    baseURL: baseURL,
    timeout: 20000,
    headers: {
        'Content-Type': 'application/json'
    },
    withCredentials: true
})

module.exports = {

    //args, options, logger for each action

login () {
        log.w("waiting for login ...")
        const ruid = uid()
        curl({method:'get',url:`${baseURL}/auth/setup?ruid=${ruid}`, withCredentials: true})
        .then((response) => {
           log.c('login complete',response)
        })

        open(`${baseURL}/auth/google?ruid=${ruid}`)
        log.d("Check your browser for login\n")
    },
/**
 * 
 * @param {string} token 
 */
registerRunner(args, options, logger) {
    //
    if (!options.token) logger.error('token is required')

    log.w(`your task is running ...`)
        curl({
            method: 'POST',
            url: `${baseURL}/gitlab/runner/add`,
            data: {
                runner_token: options.token,
                url: 'https://gitlab.com',
                desc: options.desc || 'no description'
            },
            withCredentials: true
        }).then((response) => {
            if(!response.data) {
                log.s(`"${options.desc || "your token" }" has been registered`)
            }
            else log.e("bad token",response.data) 
        }).catch((error) => {
            log.e('Unuthorized : you should be login to perform this action')
            log.d(`plesae run : opensi login`)
            log.d('error',error)

        })
},

/**
 * 
 */
logout(){
    log.w(`disconnecting ...`)
    try {
        curl({
            method: 'GET',
            url: `${baseURL}/logout`,
        }).then((response) => {
            log.c(`you are now disconnected`)
        }).catch((result) => {
            log.c(`you are now disconnected`)
        })
    } catch (error) {
        log.e(error)
    }
}
}